  "Fold a ridge in the middle of the baking paper and spread the walnut batter on one half, the cocoa batter on the other, about 1 cm thick.": "Διπλώστε μια πτυχή στη μέση του λαδόχαρτου και απλώστε το μείγμα με καρύδι στη μία μισή και το μείγμα με κακάο στην άλλη, πάχους περίπου 1 εκ.",
  "Evenly spread": "Απλωμένο ομοιόμορφα",
