  "Custard base": "Βάση κρέμας",
  "Whisk the yolks, the sugar and the flour smooth with a few spoons of the milk. Heat the rest of the milk in the saucepan until it steams.": "Χτυπήστε τους κρόκους, τη ζάχαρη και το αλεύρι με λίγες κουταλιές γάλα μέχρι να γίνουν λεία. Ζεστάνετε το υπόλοιπο γάλα στο κατσαρολάκι μέχρι να αχνίσει.",
  "Smooth base, milk steaming": "Λεία βάση, γάλα που αχνίζει",
  "Cook the custard": "Μαγειρέψτε την κρέμα",
