  "Thick, coats the whisk": "Πηχτή, πασαλείβει το σύρμα",
  "Cool the custard": "Κρυώστε την κρέμα",
  "Pour into a bowl, press cling film onto the surface and let it cool.": "Μεταφέρετέ τη σε μπολ, βάλτε μεμβράνη απευθείας στην επιφάνεια και αφήστε τη να κρυώσει.",
