  "Make the syrup": "Φτιάξτε το σιρόπι",
  "Boil the water and the sugar with the lemon zest for 2 minutes. Take off the heat and add the rest of the rum.": "Βράστε το νερό και τη ζάχαρη με ξύσμα λεμονιού για 2 λεπτά. Αποσύρετε από τη φωτιά και προσθέστε το υπόλοιπο ρούμι.",
  "Syrupy": "Σιροπιαστό",
