  "Roughly chop the walnuts for the layers.": "Χοντροκόψτε τα καρύδια για τις στρώσεις.",
  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "Κόψτε τα παντεσπάνια σε χοντρά κομμάτια. Σε βαθύ σκεύος στρώστε παντεσπάνι με καρύδι, το μισό σιρόπι, τη μισή κρέμα, τις μισές σταφίδες και καρύδια· μετά παντεσπάνι με κακάο, το υπόλοιπο σιρόπι, σταφίδες και καρύδια, και τελειώστε με την κρέμα.",
  "Cover and chill for at least 4 hours; overnight is best.": "Σκεπάστε και βάλτε στο ψυγείο για τουλάχιστον 4 ώρες· ιδανικά όλη τη νύχτα.",
